svg.script:
// 
const width = 9, height = 9, mines = 10;
let clicked = false, clicking = false;
let chording = false, chordSrc = -1, chordFlagging = false;
let start, timerRunning = false;

function around(i) {
	const ret = [i-width, i+width];
	if (i % width) ret.push(i-width-1, i-1, i+width-1);
	if ((i+1) % width) ret.push(i-width+1, i+1, i+width+1);
	return ret.sort();
}

function getTile(i) {
	return document.querySelector(`#board use[i="${i}"]`);
}

function setLCD(lcd, value, digits) {
	value = Math.max(0, Math.min(value, Math.pow(10, digits)-1));
	--digits;
	for (let i=Math.pow(10, digits); i > 0; i = Math.trunc(i / 10)) {
		const digit = Math.trunc(value / i);
		const panel = document.getElementById(`${lcd}${digits}`);
		panel.classList.remove("n0", "n1", "n2", "n3", "n4", "n5", "n6", "n7", "n8", "n9");
		panel.classList.add(`n${digit}`);
		value -= digit * i;
		--digits;
	}
}

function runTimer(ts) {
	if (!timerRunning) return;
	if (!start) {
		start = ts;
	}
	setLCD("time", Math.trunc((ts - start) / 1000), 3);
	requestAnimationFrame(runTimer);
}

function updateMines() {
	const m = mines - document.querySelectorAll(".flagged").length;
	setLCD("mines", m, 3);
}

function tileMouseDown(e) {
	if (e.buttons & 3 && e.target.classList.contains("open"))
		previewChord(parseInt(e.target.attributes.i.value), e.buttons & 2);
	else if (e.buttons & 2) {
		e.target.classList.toggle("flagged");
		updateMines();
	}
	else if (e.buttons & 1 && !e.target.classList.contains("flagged")) {
		e.target.classList.add("clicking");
		clicking = true;
	}
}

function gameMouseUp(e) {
	for (let x of document.querySelectorAll(".clicking")) {
		x.classList.remove("clicking");
	}
	if (chording) chord(chordSrc, chordFlagging);
	clicking = chording = false;
	document.querySelector(".reset-border").classList.remove("clicked");
}
document.getElementById("game").addEventListener("mouseup", gameMouseUp);

function tileMouseUp(e) {
	if (clicking && !e.target.classList.contains("flagged")) {
		const i = parseInt(e.target.attributes.i.value);
		if (e.target.classList.contains("open")) chord(i);
		else reveal(i);
	}
	gameMouseUp(e);
}

function tileMouseLeave(e) {
	e.target.classList.remove("clicking");
}

function tileMouseEnter(e) {
	if (timerRunning) {
		const reset = document.getElementById("reset");
		midpoint = parseInt(reset.attributes.x.value) + parseInt(reset.attributes.width.value) / 2;
		if (e.target.attributes.x.value < midpoint) {
			reset.attributes.href.value = "rsc/look_left.png";
		}
		else if(e.target.attributes.x.value > midpoint) {
			reset.attributes.href.value = "rsc/look_right.png";
		}
	}
	if (!chording) tileMouseDown(e);
}

function preventDefault(e) {
	e.preventDefault();
}

function listenTiles() {
	for(let e of document.querySelectorAll(".tile")) {
		e.addEventListener("mousedown", tileMouseDown);
		e.addEventListener("mouseup", tileMouseUp);
		e.addEventListener("mouseleave", tileMouseLeave);
		e.addEventListener("mouseenter", tileMouseEnter);
		e.addEventListener("contextmenu", preventDefault);
	}
}

function reveal(i) {
	const t = getTile(i);
	if (!t || t.classList.contains("open") || t.classList.contains("flagged")) return;
	t.classList.add("open");
	const n = parseInt(t.attributes.href.value.substring(5));
	if (n == 0) {
		clicked = timerRunning = true;
		around(i).forEach(reveal);
		requestAnimationFrame(runTimer);
		checkWon();
	}
	else if (!clicked) {
		fillTiles(i);
		reveal(i);
	}
	else if (n == -1) lose()
}

function status(i) {
	const t = getTile(i);
	if (!t) return NaN;
	if (t.classList.contains("open")) return 0;
	if (t.classList.contains("flagged")) return 2;
	return 1;
}

function previewChord(i, flagging) {
	const t = getTile(i);
	if (!t || !t.classList.contains("open")) return;
	chording = true;
	chordSrc = i;
	chordFlagging = flagging;
	const n = parseInt(t.attributes.href.value.substring(5));
	if (n > 0) {
		for(let x of around(i)) {
			const tt = getTile(x);
			if (tt && !tt.classList.contains("open") && !tt.classList.contains("flagged")) {
				tt.classList.add("clicking");
			}
		}
	}
}

function chord(i, flagging) {
	const t = getTile(i);
	if (!t || !t.classList.contains("open")) return;
	const n = parseInt(t.attributes.href.value.substring(5));
	const states = around(i).map(status);
	const unopened = states.filter(x => x === 1).length;
	const flagged = states.filter(x => x === 2).length;
	if (flagging) {
		if (unopened + flagged === n) {
			for(let x of around(i)) {
				const tt = getTile(x);
				if (tt && !tt.classList.contains("open"))
					tt.classList.add("flagged");
			}
			updateMines();
		}
	} else if (flagged === n) {
		around(i).forEach(reveal);
		checkWon();
	}
}

function checkWon() {
	if (!document.querySelectorAll('#board .tile:not(.open):not([href="#tile-1"])').length) {
		timerRunning = false;
		document.getElementById("reset").attributes.href.value = "rsc/won.png"
	}
}

function lose() {
	document.getElementById("board").classList.add("lost");
	document.getElementById("reset").attributes.href.value = "rsc/lost.png"
	timerRunning = false;
}

function fillTiles() {
	document.getElementById("board").classList.remove("lost");
	clicked = timerRunning = false; start = undefined;
	const bd = document.getElementById("board");
	const bd_x = parseInt(bd.attributes.x.value),
		bd_y = parseInt(bd.attributes.y.value),
		bd_w = parseInt(bd.attributes.width.value),
		bd_h = parseInt(bd.attributes.height.value);
	const tw = bd_w / width;
	const th = bd_h / height;
	let data = "";
	let tiles = "";
	let field = new Array(width * height).fill(0).fill(-1, 0, mines);
	for(let i=0; i<3; ++i) field.sort(() => Math.random() - 0.5);
	function tryInc(pos) {
		if (pos >= 0 && pos < field.length && field[pos] >= 0)
			++field[pos]
	}
	for(i=0; i < field.length; ++i) {
		if (field[i] < 0) {
			const x = i % width;
			if (x > 0) {
				tryInc(i-width-1);
				tryInc(i-1);
				tryInc(i+width-1);
			}
			tryInc(i-width);
			tryInc(i+width);
			if (x+1 < width) {
				tryInc(i-width+1);
				tryInc(i+1);
				tryInc(i+width+1);
			}
		}
	}
	for(let y=bd_y, i=0; y < bd_y + bd_w; y += th) {
		for (let x=bd_x; x < bd_x + bd_h; x += tw, i++) {
			tiles += `<use class="tile" x="${x}" y="${y}" i="${i}" width="${tw}" height="${th}" href="#tile${field[i]}" />`
		}
	}
	bd.innerHTML = tiles;
	listenTiles();
	updateMines();
	setLCD("time", 0, 3);
}
fillTiles();

function resetMouseDown() {
	document.querySelector(".reset-border").classList.add("clicked");
	document.getElementById("reset").attributes.href.value = "rsc/start.png";
}

function resetMouseUp() {
	document.querySelector(".reset-border").classList.remove("clicked");
	fillTiles();
}

document.getElementById("reset").addEventListener("mousedown", resetMouseDown);
document.getElementById("reset").addEventListener("mouseup", resetMouseUp);
//
